"""Sweep: build several topologies, export every interval, verify offline.

Runs identically on POSIX and Windows; reports any divergence between the
on-chain verdict and the offline range-proof verdict (and tamper detection).
"""
import copy
import json
import os
import sys
import tempfile

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from audit_chain import Chain, verify_proof

FAILURES = []


def check(cond, msg):
    if not cond:
        FAILURES.append(msg)
        print("FAIL:", msg)


def build(kind):
    tmp = tempfile.mkdtemp(prefix=f"sweep-{kind}-")
    path = os.path.join(tmp, "log")
    dest = os.path.join(tmp, "archive")
    c = Chain(path)
    n = 0

    def add(t, i):
        c.append(t, {"i": i})

    if kind == "basic":
        for r in range(4):
            add("t", n); add("u", n); n += 1
        c.rotate()
        for r in range(4):
            add("t", n); add("u", n); n += 1
        c.rotate()
        for r in range(4):
            add("t", n); n += 1
        c.archive(dest)
    elif kind == "append_after_archive":
        for r in range(4):
            add("t", n); add("u", n); n += 1
        c.rotate()
        for r in range(4):
            add("t", n); add("u", n); n += 1
        c.archive(dest)
        for r in range(6):
            add("t", n); n += 1
    elif kind == "compact_after_archive":
        for r in range(3):
            add("t", n); add("u", n); n += 1
        c.rotate()
        for r in range(3):
            add("t", n); add("u", n); n += 1
        c.rotate()
        for r in range(3):
            add("t", n); add("u", n); n += 1
        c.rotate()
        for r in range(3):
            add("t", n); n += 1
