import copy
import os
import random
import shutil
import sys
import tempfile

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from audit_chain import Chain, verify_proof


def run(seed):
    rng = random.Random(seed)
    tmp = tempfile.mkdtemp(prefix=f"fuzz-{seed}-")
    path = os.path.join(tmp, "log")
    dest = os.path.join(tmp, "archive")
    c = Chain(path)
    total = 0
    archived = False
    compacted_hot = False
    ops = []

    def add():
        nonlocal total
        c.append("t", {"i": total, "pad": "z" * rng.randrange(0, 5)})
        total += 1

    try:
        for _ in range(rng.randrange(6, 14)):
            op = rng.choice(["add", "add", "add", "rotate", "archive", "compact"])
            if op == "add":
                for _ in range(rng.randrange(1, 4)):
                    add()
            elif op == "rotate":
                c.rotate()
                ops.append("rotate")
            elif op == "archive":
                try:
                    r = c.archive(dest)
                    archived = archived or r["archived"] > 0
                    ops.append(f"archive:{r['archived']}")
                except ValueError as e:
                    ops.append(f"archive-err:{e}")
            elif op == "compact":
                try:
                    r = c.compact(rng.choice([1, 2, 3]))
                    compacted_hot = True
                    ops.append(f"compact:{r['segments']}")
                except ValueError as e:
                    ops.append(f"compact-err")
        for _ in range(3):
            add()

        chain_v = c.verify("t")
        # exercise all intervals (bounded step)
        for s in range(0, total, 3):
            for e in range(s + 1, min(total, s + 6) + 1):
                proof = c.export_range("t", s, e)
                rv = verify_proof(proof, tenant="t", start=s, end=e)
                if not rv["ok"] or rv["first_bad"] != -1 or rv["count"] != e - s:
                    return ("FALSE_BAD", seed, ops, chain_v, (s, e), rv)
                # cold path
                cache = os.path.join(path, ".verify-cache")
                had = os.path.exists(cache)
                if had:
                    os.rename(cache, cache + ".bak")
                try:
                    proof2 = c.export_range("t", s, e)
                    rv2 = verify_proof(proof2, tenant="t", start=s, end=e)
                    if not rv2["ok"] or rv2["first_bad"] != -1:
                        return ("FALSE_BAD_COLD", seed, ops, chain_v, (s, e), rv2)
                finally:
                    if had:
                        os.rename(cache + ".bak", cache)
                # tamper the middle record
                mid = (s + e) // 2
                bad = copy.deepcopy(proof)
                for w in bad["windows"]:
                    for slot in w["records"]:
                        if slot["index"] == mid:
                            slot["record"]["payload"] = {"i": -1}
                tv = verify_proof(bad)
                if tv["ok"] or tv["first_bad"] != mid:
                    return ("TAMPER_MISS", seed, ops, chain_v, (s, e), mid, tv)
        return None
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


found = None
for seed in range(300):
    res = run(seed)
    if res:
        found = res
        print(res[0], "seed=", res[1])
        print("ops:", res[2])
        print("chain verdict:", res[3])
        print("interval:", res[4], "verdict:", res[5] if res[0] != "TAMPER_MISS" else res[6])
        break
if not found:
    print("no divergence in 300 seeds")

